def edit_distance(a: str, b: str) -> int:
    # Base case: if a is empty, return the number of deletions needed
    if a == '':
        return len(b)

    # Base case: if b is empty, return the number of insertions needed
    if b == '':
        return len(a)

    # Recursive case: insert a character to a, or delete a character from b
    # or replace a character in a with one in b
    # We use dynamic programming to compute the minimum number of operations
    # The DP table is (len(a)+1) x (len(b)+1)

    # Initialize DP table
    dp = [[0] * (len(b)+1) for _ in range(len(a)+1)]

    # Fill the DP table
    for i in range(len(a)+1):
        for j in range(len(b)+1):
            if i == 0 and j == 0:
                dp[i][j] = 0
            elif i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1] + 1)

    # The answer is the minimum number of operations
    return dp[len(a)][len(b)]
